/* @autogenerated */
import { DOCUMENT } from '@angular/common';
import { computed, effect, EnvironmentProviders, inject, Injectable, provideAppInitializer } from '@angular/core';
import { APP_CONFIG } from '../config/app-config.service';
import { BrandConfig, ThemeConfig } from '../config/app-config.model';
import { AppStateService } from '../state/app-state.service';
import { ThemeModeService } from './theme-mode.service';

/** Logo que se usa si la configuración no trae `theme.logo`. */
export const DEFAULT_LOGO = 'assets/img/logo-75x75.png';

/** Tokens efectivos: los de `theme.tokens` con los del tenant activo encima. */
export function resolveTokens(theme: ThemeConfig, tenant: string): Record<string, string> {
  return { ...theme.tokens, ...theme.tenants?.[tenant]?.tokens };
}

/** Marca efectiva: la del tenant activo y, campo a campo, la general. */
export function resolveBrand(theme: ThemeConfig, tenant: string): BrandConfig {
  const override = theme.tenants?.[tenant] ?? {};
  return {
    logo: override.logo ?? theme.logo,
    'logo-dark': override['logo-dark'] ?? (override.logo ? undefined : theme['logo-dark']),
    'product-name': override['product-name'] ?? theme['product-name'],
  };
}

/**
 * Aplica `theme.tokens` (y `theme.tenants.<tenant>.tokens`) como custom properties en `<html>`, sin recompilar,
 * y expone el logo y el nombre del producto para el shell.
 */
@Injectable({ providedIn: 'root' })
export class RuntimeThemeService {
  private readonly root = inject(DOCUMENT).documentElement;
  private readonly config = inject(APP_CONFIG);
  private readonly tenant = inject(AppStateService).tenant;
  private readonly themeMode = inject(ThemeModeService);
  /** Propiedades fijadas en la última aplicación: al cambiar de tenant se quitan las que ya no tocan. */
  private applied = new Set<string>();

  readonly tokens = computed(() => resolveTokens(this.config().theme, this.tenant()));
  private readonly brand = computed(() => resolveBrand(this.config().theme, this.tenant()));

  /** Logo según el modo claro/oscuro efectivo. */
  readonly logo = computed(() => {
    const brand = this.brand();
    return (this.themeMode.dark() && brand['logo-dark']) || brand.logo || DEFAULT_LOGO;
  });

  /** Nombre del producto: `theme.product-name` o, si falta, `meta.title`. */
  readonly productName = computed(() => this.brand()['product-name'] ?? this.config().meta.title ?? '');

  constructor() {
    effect(() => this.apply(this.tokens()));
  }

  private apply(tokens: Record<string, string>): void {
    const style = this.root.style;
    this.applied.forEach((name) => {
      if (!(name in tokens)) {
        style.removeProperty(name);
      }
    });
    Object.entries(tokens).forEach(([name, value]) => style.setProperty(name, value));
    this.applied = new Set(Object.keys(tokens));
  }
}

/** Aplica los tokens de la configuración en cuanto se cargan, antes de pintar el shell. */
export function provideRuntimeTheme(): EnvironmentProviders {
  return provideAppInitializer(() => {
    inject(RuntimeThemeService);
  });
}
